const b = $input.first().json.body || {};
if (!b.case_id) { throw new Error('missing case_id'); }
const ok = ['cremation','burial','unknown'].includes(b.preference);
return [{ json: { case_id: b.case_id, preference: ok ? b.preference : 'unknown', callback: b.callback, on_call_director: 'Director (FICTIONAL)', removal_team: 'queued', dispatched_at: new Date().toISOString() } }];
